#!/bin/bash
# Section 9 -- GATE B, Terrier metric parity.
#
# NOT RUN in this phase: no Terrier, no trec_eval and NO JAVA RUNTIME on this
# machine, and resolution item 6 forbids installing a JRE or any system-level
# dependency. terrier_parity.json is therefore recorded as NOT_ATTEMPTED and the
# section 8.6 exclusion fallback governs the IDCG==0 policy.
#
# Everything Gate B needs is already generated by build_terrier_files.py:
#   trec_eval_data/synthetic.qrels    synthetic.results
#   trec_eval_data/dev_random.qrels   dev_random.results
#   trec_eval_data/dev_bm25.qrels     dev_bm25.results
#
# To complete Gate B later:
#   1. install a JRE and Terrier 5.5   (https://github.com/terrier-org/terrier-core)
#   2. ./run_terrier_parity.sh /path/to/terrier-project-5.5/bin/terrier
#   3. read the printed nDCG values into terrier_parity.json, set status=PASS/FAIL,
#      set output_decimal_places and tolerance = max(1e-6, 0.5 * 10**-d),
#      and record the observed IDCG==0 behaviour from the synthetic set
#   4. if the observed policy differs from "exclude", re-run
#      evaluate_task1_baselines.py with the corrected policy and bump
#      manifest_revision in test_lock_manifest.json
#
# The gain spec below is the CORRECTED one. The qrels written by
# build_terrier_files.py use I->1, C->2, S->3, E->4, so composing with
# 'ndcg.1=0,2=0.01,3=0.1,4=1' gives E=1.0, S=0.1, C=0.01, I=0.0. The reference
# helper's own mapping ({E:4,S:2,C:3,I:1}) would give S=0.01 and C=0.1 --
# do NOT reproduce it. See gain_convention_conflict.json.

set -euo pipefail

if [ "$#" -ne 1 ]; then
    echo "usage: ./run_terrier_parity.sh \${BIN_TERRIER_CORE_PATH}"
    echo "example: ./run_terrier_parity.sh /tmp/terrier-project-5.5/bin/terrier"
    exit 1
fi

TERRIER="$1"
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TREC_DIR="$(dirname "${HERE}")/trec_eval_data"
GAIN_SPEC='ndcg.1=0,2=0.01,3=0.1,4=1'

echo "terrier binary : ${TERRIER}"
echo "trec_eval_data : ${TREC_DIR}"
echo "gain spec      : ${GAIN_SPEC}   (CORRECTED I->1 C->2 S->3 E->4 qrels)"
echo

for NAME in synthetic dev_random dev_bm25; do
    QRELS="${TREC_DIR}/${NAME}.qrels"
    RES="${TREC_DIR}/${NAME}.results"
    if [ ! -f "${QRELS}" ] || [ ! -f "${RES}" ]; then
        echo "SKIP ${NAME}: input files missing (run build_terrier_files.py first)"
        continue
    fi
    echo "=== ${NAME} ==="
    "${TERRIER}" trec_eval "${QRELS}" "${RES}" -c -J -m "${GAIN_SPEC}"
    echo
done

echo "Compare each nDCG against python_ndcg_full_by_policy in"
echo "  ${TREC_DIR}/trec_files_manifest.json"
echo "and record the result in terrier_parity.json."
